import{_ as a,o as s,c as i,a0 as n}from"./chunks/framework.C3yZ6M33.js";const u=JSON.parse('{"title":"Fleet runners (runs_on)","description":"","frontmatter":{},"headers":[],"relativePath":"reference/fleet-runners.md","filePath":"reference/fleet-runners.md"}'),t={name:"reference/fleet-runners.md"};function o(r,e,d,l,c,h){return s(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="fleet-runners-runs-on" tabindex="-1">Fleet runners (<code>runs_on</code>) <a class="header-anchor" href="#fleet-runners-runs-on" aria-label="Permalink to &quot;Fleet runners (`runs_on`)&quot;">​</a></h1><p>Peregrin nodes can advertise <strong>runner labels</strong> and campaigns can declare which labels they require. Scheduling rides Hypha&#39;s entity plane — campaign entities, <code>campaign.start</code> ops, ownership and locks — never a separate lease protocol.</p><h2 id="node-labels" tabindex="-1">Node labels <a class="header-anchor" href="#node-labels" aria-label="Permalink to &quot;Node labels&quot;">​</a></h2><p><code>PEREGRIN_RUNNER_LABELS</code> is a comma-separated list appended to the node&#39;s <code>/api/node</code> <code>capabilities</code> (alongside <code>ephemeral</code>, <code>sessions</code>, …):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PEREGRIN_RUNNER_LABELS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">runner:linux,gpu</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> peregrin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ephemeral</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PEREGRIN_RUNNER_LABELS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">runner:linux,gpu</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> peregrin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> campaign</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci-gate.yaml</span></span></code></pre></div><p>The hub&#39;s sync projection persists the advertised capability list, so fleet members are discoverable via node status.</p><h2 id="campaign-runs-on" tabindex="-1">Campaign <code>runs_on</code> <a class="header-anchor" href="#campaign-runs-on" aria-label="Permalink to &quot;Campaign `runs_on`&quot;">​</a></h2><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">gpu-train</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">runs_on</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">runner:linux</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">gpu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">nodes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>Every <code>runs_on</code> entry must appear in the node&#39;s advertised capabilities (AND semantics; absent <code>runs_on</code> runs anywhere). The gate is enforced in two places:</p><ul><li><strong><code>campaign.start</code> entity ops</strong> — the campaign entity plane on the owning node rejects a start whose <code>runs_on</code> the node doesn&#39;t satisfy (<code>409</code>), so a misrouted op fails loudly instead of running on the wrong hardware. Combined with Hypha ownership + locks, only the entity&#39;s owner can launch it — two nodes can&#39;t claim the same campaign entity.</li><li><strong><code>campaign serve</code> hosting</strong> — campaigns whose <code>runs_on</code> isn&#39;t satisfied are skipped at startup (warned); if none match, serve exits with an error rather than hosting half a fleet.</li></ul><h2 id="job-isolation" tabindex="-1">Job isolation <a class="header-anchor" href="#job-isolation" aria-label="Permalink to &quot;Job isolation&quot;">​</a></h2><p><code>driver: shell</code> params accept:</p><ul><li><code>isolate: true</code> — run the command inside <code>systemd-run --user --scope --collect</code>.</li><li><code>memory_max: &quot;512M&quot;</code> — adds <code>-p MemoryMax=…</code> and implies <code>isolate</code>.</li></ul><p>Both require <code>systemd-run</code> on <code>PATH</code> and a working <code>systemd --user</code> manager; without them the node fails with <code>node.failed</code> — isolation is never silently dropped. <code>bupha</code>-imported jobs carry <code>isolate</code> / <code>memory_max</code> through to the inner shell driver automatically.</p><p>Deferred: cgroup v2 direct manipulation, container/VM isolation, per-job CPU/IO limits beyond <code>MemoryMax</code>.</p><h2 id="ephemeral-node-recovery" tabindex="-1">Ephemeral-node recovery <a class="header-anchor" href="#ephemeral-node-recovery" aria-label="Permalink to &quot;Ephemeral-node recovery&quot;">​</a></h2><p>An ephemeral runner (<code>--ephemeral</code> / <code>PEREGRIN_EPHEMERAL</code>) that dies mid-run is reaped by the hub after <code>PEREGRIN_EPHEMERAL_DEAD_AFTER</code>: its projected entities drop and outbox writes queued for it dead-letter. Campaign entities hosted by <code>campaign serve</code> keep their durable SQLite queue — on restart, interrupted runs requeue at the front per the queue&#39;s at-least-once semantics, and <code>supersede</code> keys still dedupe retriggered work.</p><h2 id="hub-side-dispatch" tabindex="-1">Hub-side dispatch <a class="header-anchor" href="#hub-side-dispatch" aria-label="Permalink to &quot;Hub-side dispatch&quot;">​</a></h2><p>When a campaign entity is created through the hub <strong>without</strong> an explicit node pin (<code>POST /api/entities</code>, no <code>node</code> field or <code>?node=</code>) and its declared <code>runs_on</code> labels are non-empty, the hub&#39;s <code>FleetDispatchApi</code> decorator picks an eligible node automatically:</p><ul><li>Eligible = node <code>status != &quot;down&quot;</code> and <code>runs_on</code> satisfied over the node&#39;s persisted <code>capabilities</code> labels.</li><li>Sort order is <code>(ephemeral, id)</code> — durable nodes are preferred, ephemeral runners are the fallback; ties break on node id, so the pick is fully deterministic.</li><li>The created entity is then <em>owned</em> by the picked node, so <code>campaign.start</code> ops route there and pass the existing label gate.</li></ul><p>Callers can still pin explicitly (<code>node</code> field / <code>?node=</code>); pinned or label-less creates pass through untouched. Known seams: moving an entity already pinned to an ineligible node is snapshot export/import territory; there is no re-dispatch on node death and no load-aware scheduling yet.</p>',21)])])}const k=a(t,[["render",o]]);export{u as __pageData,k as default};
